mapper.update:
UPDATE content_event_outbox
SET status = 'SENT', sent_at = #{now}, lease_owner = NULL,
    lease_until = NULL, last_error = NULL
WHERE event_id = #{eventId}
  AND 
  AND status = 'SENDING'
  AND lease_owner = #{leaseOwner}
  AND lease_until > #{now}

UPDATE content_event_outbox
SET status = #{status}, next_attempt_at = #{nextAttemptAt},
    lease_owner = NULL, lease_until = NULL, last_error = #{errorCode}
WHERE event_id = #{eventId}
  AND 
  AND status = 'SENDING'
  AND lease_owner = #{leaseOwner}
  AND lease_until > #{now}

mapper.delete:
DELETE FROM content_event_outbox
WHERE 
  AND status = 'SENT'
  AND sent_at < #{sentBefore}
ORDER BY sent_at ASC, event_id ASC
LIMIT #{limit}
